//! Generated host bindings for the Lean-defined gateway world.
//!
//! `wit/gateway.wit` is GENERATED by schema-lang from `Demo.lean` (the
//! SSOT) — the @[schema] records/variants/funcs. `bindgen!` turns that
//! single world into TYPED host glue: the `Gateway` trait's methods take
//! and return Rust structs generated from the WIT records (User,
//! OrderError, Role), not raw component [`Val`]s. This is the "Lean
//! defines the ABI" proof: the host's API is produced from the Lean spec,
//! byte-tied, and anything the Lean side renames renames the host API.
//!
//! The generated `User` here is the SAME shape as `schema_generated::User`
//! (both from the same Lean records) — connect them where shared use
//! needs a single type.

// The macro needs the WIT resolvable relative to this crate's root
// (crates/steel-host → ../../ = repo root).
wasmtime::component::bindgen!({
    path: "../../wit/gateway.wit",
    world: "gateway",
    async: true,
});

/// Canonical alias: the bindgen-generated `User` (from `record user`).
pub type GatewayUser = User;
/// Canonical alias: the bindgen-generated `OrderError` variant type.
pub type GatewayOrderError = OrderError;
